const raw = $input.first().json;
const content = raw.choices?.[0]?.message?.content || '{}';

let classification;
try {
  const cleaned = content.replace(/```json|```/g, '').trim();
  classification = JSON.parse(cleaned);
} catch (e) {
  classification = { domain: 'general', complexity: 'medium', task_type: 'other', one_liner: 'General request' };
}

const prev = $('Parse Input').first().json;

const modelMap = {
  high:   'llama-3.3-70b-versatile',
  medium: 'llama-3.1-70b-versatile',
  low:    'llama-3.1-8b-instant'
};

const model = modelMap[classification.complexity] || 'llama-3.1-70b-versatile';

return [{
  json: {
    message: prev.message,
    sessionId: prev.sessionId,
    timestamp: prev.timestamp,
    domain: classification.domain,
    complexity: classification.complexity,
    task_type: classification.task_type,
    one_liner: classification.one_liner,
    model
  }
}];

const prev = $('Select Model + Domain').first().json;
const items = $input.all().map(i => i.json);

const events = items.filter(e => e && e.id && !e.error);

let calendarContext;
if (events.length === 0) {
  calendarContext = 'No events found on the calendar for today.';
} else {
  calendarContext = events.map(e => {
    let time = 'All day';
    if (e.start && e.start.dateTime) {
      time = new Date(e.start.dateTime).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
    }
    return `- ${time}: ${e.summary || 'Untitled event'}`;
  }).join('\n');
}

return [{ json: { ...prev, calendarContext } }];

const domain = $json.domain;

const groundingRule = `

CRITICAL GROUNDING RULES:
- You do NOT have access to Jasmine's email, texts, or notifications unless explicitly provided in this conversation.
- NEVER invent, guess, or fabricate specific meeting times, appointments, messages, birthdays, or deadlines beyond what is provided to you (including the real calendar data below, if present).
- Do not state times, dates, or scheduled items as fact unless they come from the real calendar data below or were given to you in the current request.
- It is always better to say "I don't have that information" than to make something up. Jasmine relies on you for accuracy.`;

const calendarSection = $json.calendarContext
  ? `

TODAY'S ACTUAL CALENDAR (real data pulled from Jasmine's Google Calendar just now):
${$json.calendarContext}

When asked about the schedule, meetings, or events, use ONLY this list. Do not add, guess, or embellish beyond what's shown here. If the list says no events were found, say so plainly.`
  : '';

const systemPrompts = {
  general: `You are Jarvis, Jasmine Mack's personal AI assistant.

Jasmine is an AI creative technologist, automation builder, and fractional ops consultant based in Tampa/Sarasota. She runs Dynamack Operations LLC, is embedded at L2 Global, and is building Signl Cycle (a PMDD cycle-tracking app) and Berry the Bear (an animated awareness series). She is also a poet (pen name Jasmine Gabrielle) and has a goldendoodle named Luna.

Be helpful, direct, and match her energy — sharp, systems-minded, creative, faith-grounded. You know her context well.`
};

const systemPrompt = (systemPrompts[domain] || systemPrompts.general) + groundingRule + calendarSection;

return [{ json: { ...$json, systemPrompt } }];

const current = $('Build System Prompt').first().json;
const memoryRows = $input.all().map(r => r.json).filter(r => r.session_id);

const historyMessages = memoryRows
  .sort((a, b) => new Date(a.created_at) - new Date(b.created_at))
  .flatMap(row => [
    { role: 'user', content: row.user_message },
    { role: 'assistant', content: row.assistant_response }
  ])
  .filter(m => m.content);

const messages = [
  { role: 'system', content: current.systemPrompt },
  ...historyMessages,
  { role: 'user', content: current.message }
];

return [{ json: { ...current, messages } }];

const groqRes = $input.first().json;
const ctx = $('Build Message History').first().json;

const responseText = groqRes.choices?.[0]?.message?.content || 'No response generated.';
const modelUsed = groqRes.model || ctx.model;
const inputTokens = groqRes.usage?.prompt_tokens || 0;
const outputTokens = groqRes.usage?.completion_tokens || 0;

return [{
  json: {
    sessionId: ctx.sessionId,
    domain: ctx.domain,
    complexity: ctx.complexity,
    task_type: ctx.task_type,
    one_liner: ctx.one_liner,
    model_used: modelUsed,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    user_message: ctx.message,
    assistant_response: responseText,
    timestamp: ctx.timestamp
  }
}];
